window.getRegionLabel = function(tag, fallback) {
  const lang = (window.GDMMLang && GDMMLang.getLang && GDMMLang.getLang()) || 'en';
  const dict = window.REGION_LABELS[lang] || window.REGION_LABELS.en || {};
  return dict[tag] || fallback || tag;
};

